\begin{lemma}[Jensen-type inequality for gradients]
  \label{lem:gradient_jensen}
  Under \cref{asm:hessian_lip}, the following holds for any $z_1, \dots, z_n \in \R^d$ and $\lambda_1,\dots,\lambda_n \geq 0$ such that $\sum_{i=1}^n \lambda_i = 1$:
  \begin{align}
    \norm*{
      \nabla f \prn*{ \sum_{i=1}^n \lambda_i z_i }
      - \sum_{i=1}^n \lambda_i \nabla f \prn*{ z_i }
    }
    \leq
    \frac{\Mtrue}{2} \sum_{1 \leq i < j \leq n} \lambda_i \lambda_j \norm*{z_i - z_j}^2.
  \end{align}
\end{lemma}

\begin{lemma}[Error bound for trapezoidal rule]
  \label{lem:trapezoidal_rule_error}
  Under \cref{asm:hessian_lip}, the following holds for any $x, y \in \R^d$:
  \begin{align}
    f(x) - f(y)
    &\leq
    \frac{1}{2} \inner*{\nabla f(x) + \nabla f(y)}{x - y}
    + \frac{\Mtrue}{12} \norm*{x - y}^3.
  \end{align}
\end{lemma}

\begin{proposition}
  \label{prop:L_upperbound}
  Suppose that \cref{asm:gradient_lip} holds.
  Then, the following is true throughout \cref{alg:proposed_agd}: $\Lest \leq \max\set{\Linit, \alpha \Ltrue}$.
\end{proposition}

\begin{lemma}
  \label{lem:decrease_epoch}
  Suppose that \cref{asm:gradient_lip} holds.
  During epochs with $\Lest \geq \Ltrue$, condition~\cref{eq:descent_condition} always holds.
\end{lemma}

\begin{lemma}
  \label{lem:potential_decrease_iteration}
  Under \cref{asm:gradient_lip} and $\Lest \geq \Ltrue$, the following holds for all $k \geq 0$:
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 + \theta_k - 2}{4} \Lest \norm*{x_{k+1} - x_k}^2
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3\\
    &\quad
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
    \label{eq:potential_decrease_iteration}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{lem:potential_decrease_iteration}]
  In the proof, let
  \begin{align}
    P_k
    &\coloneqq
    \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
  \end{align}
  to simplify the notation.
  From \cref{lem:eq:property_gradlip_obj,eq:update_xy}, we have
  \begin{align}
    f(x_{k+1}) - f(y_k)
    &\leq
    \inner*{\nabla f(y_k)}{x_{k+1} - y_k}
    + \frac{\Lest}{2} \norm*{x_{k+1} - y_k}^2
    = 
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2.
  \end{align}
  Summing this bound and \cref{eq:fy_fx_diff_upperbound_Mestk} yields
  \begin{alignat}{2}
    &\mathInd
    f(x_{k+1}) - f(x_k)
    \label{eq:descent_f_first}\\
    &\leq
    \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
    + \frac{\Mest_k}{12} \norm*{y_k - x_k}^3
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2\\
    &\leq
    \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
    + \frac{\theta_k^2 \Mest_k}{12} \norm*{x_k - x_{k-1}}^3
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2,
  \end{alignat}
  where the last inequality uses \cref{eq:update_xy} and $0 \leq \theta_k \leq 1$.
  To evaluate the first term on the right-hand side, we decompose it into four terms:
  \begin{align}
    &\mathInd
    \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}\\
    &=
    \underbrace{2 \inner*{\nabla f(y_k)}{y_k - x_k}}_{\text{(A)}}
    {}+{} \underbrace{\theta_k \inner*{\nabla f(x_{k-1})}{y_k - x_k}}_{\text{(B)}}\\[-0.8\baselineskip]
    &\quad
    - \underbrace{\theta_k \inner*{\nabla f(x_k)}{y_k - x_k}}_{\text{(C)}}
    {}-{} \underbrace{
        \inner*{
        \nabla f(y_k)
        + \theta_k \nabla f(x_{k-1})
        - (1 + \theta_k) \nabla f (x_k)
      }{y_k - x_k}
    }_{\text{(D)}}.
  \end{align}
  Each term can be evaluated as
  \begin{alignat}{2}
    \text{(A)}
    &=
    \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
    + \Lest \norm*{y_k - x_k}^2
    - \Lest \norm*{(y_k - x_k) - \frac{1}{\Lest} \nabla f(y_k)}^2\\
    &=
    \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
    + \theta_k^2 \Lest \norm*{x_k - x_{k-1}}^2
    - \Lest \norm*{x_{k+1} - x_k}^2
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(B)}
    &=
    \theta_k^2 \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
    =
    \theta_k^2 P_k
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(C)}
    &=
    - \theta_k P_{k+1}
    + \theta_k \inner*{\nabla f(x_k)}{x_{k+1} - y_k}\\
    &=
    - \theta_k P_{k+1}
    - \frac{\theta_k}{\Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(D)}
    &\leq
    \theta_k \Mest_k \norm*{x_k - x_{k-1}}^2 \norm*{y_k - x_k}
    &\quad&\by{\cref{eq:grad_interpolation_error_Mestk}}\\
    &=
    \theta_k^2 \Mest_k \norm*{x_k - x_{k-1}}^3
    &\quad&\by{\cref{eq:update_xy}}.
  \end{alignat}
  Plugging the evaluations into \cref{eq:descent_f_first} results in
  \begin{align}
    % &\mathInd
    f(x_{k+1}) - f(x_k)
    \label{eq:descent_f_second}
    &\leq
    \frac{\theta_k^2 \Lest}{2} \norm*{x_k - x_{k-1}}^2
    - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2
    + \frac{\theta_k^2}{2} P_k
    - \frac{\theta_k}{2} P_{k+1}\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    - \frac{\theta_k}{2 \Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}.
  \end{align}

  Next, to bound the last term on the right-hand side, we use the following inequality from \cref{eq:grad_interpolation_error_Mestk}:
  \begin{align}
    \norm*{
      \nabla f(y_k)
      - (1 + \theta_k) \nabla f (x_k)
    }
    &\leq
    \theta_k \norm*{ \nabla f(x_{k-1})}
    + 
    \theta_k \Mest_k
    \norm*{x_k - x_{k-1}}^2.
  \end{align}
  We square both sides as
  \begin{alignat}{2}
    &\mathInd
    \norm*{
      \nabla f(y_k)
      - (1 + \theta_k) \nabla f (x_k)
    }^2\\
    &=
    \norm*{\nabla f(y_k)}^2
    + (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
    - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}\\
    &\geq
    (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
    - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}
  \end{alignat}
  and
  \begin{alignat}{2}
    \theta_k^2 \prn*{
      \norm*{ \nabla f(x_{k-1})}
      + \Mest_k \norm*{x_k - x_{k-1}}^2
    }^2
    &\leq
    \theta_k (1 + \theta_k) \norm*{ \nabla f(x_{k-1})}^2\\
    &\quad
    + \theta_k^2 (1 + \theta_k) \Mest_k^2 \norm*{x_k - x_{k-1}}^4,
  \end{alignat}
  where we have used $(a + b)^2 \leq (1 + 1/\theta) a^2 + (1 + \theta) b^2$ for $a, b, \theta > 0$.
  Rearranging the terms yields
  \[
  % \begin{align}
    - \inner*{\nabla f (x_k)}{\nabla f(y_k)}
    \leq
    \frac{\theta_k}{2} \norm*{ \nabla f(x_{k-1})}^2
    - \frac{1 + \theta_k}{2} \norm*{\nabla f (x_k)}^2
    + \frac{\theta_k^2}{2} \Mest_k^2 \norm*{x_k - x_{k-1}}^4.
  % \end{align}
  \]
  Plugging this bound into \cref{eq:descent_f_second} results in
  \begin{align}
    \label{eq:hint_potential}
    &\mathInd
    f(x_{k+1}) - f(x_k)\\
    &\leq
    \frac{\theta_k^2}{2} \prn*{
      P_k
      + \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1})}^2
      + \Lest \norm*{x_k - x_{k-1}}^2
    }\\
    &\quad
    -
    \frac{\theta_k}{2} \prn*{
      P_{k+1} + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    }
    - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
  This inequality can be rewritten with the potential function $\Phi_k$ defined in \cref{eq:def_potential} as
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 - \theta_k}{2}
    \prn*{
      P_{k+1}
      + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    }
    + \frac{\theta_{k+1}^2 - 1}{2} \Lest \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
  Finally, using $\theta_{k+1}^2 - \theta_k \leq 0$ from \cref{eq:theta_increase_not_too_fast} and
  \begin{align}
    - P_{k+1}
    =
    - \inner*{\nabla f(x_k)}{x_{k+1} - x_k}
    \leq
    \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    + \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2
  \end{align}
  from Young's inequality ($\abs{\inner*{a}{b}} \leq \frac{1}{2} \norm*{a}^2 + \frac{1}{2} \norm*{b}^2$) yields the desired result as
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 - \theta_k}{2} \prn*{- \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2}
    + \frac{\theta_{k+1}^2 - 1}{2} \Lest \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2\\
    &=
    \frac{\theta_{k+1}^2 + \theta_k - 2}{4} \Lest \norm*{x_{k+1} - x_k}^2
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3\\
    &\quad
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
\end{proof}

\begin{proof}[Proof of \cref{lem:decrease_epoch}]
  Note that
  \begin{align}
    \sum_{i=1}^k \norm*{x_i - x_{i-1}}^3
    &\leq
    S_k^{3/2},\quad
    \sum_{i=1}^k \norm*{x_i - x_{i-1}}^4
    \leq
    S_k^2
    \label{eq:sum_xk_diff_power34_upperbound}
  \end{align}
  by the monotonicity of $\ell_p$-norms, i.e., $\norm{a}_p \geq \norm{a}_q$ for $1 \leq p \leq q$.
  In addition, we have
  \begin{align}
    \Phi_k - f(x_k)
    &=
    \frac{\theta_k^2}{2} \prn*{
      \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1}) + L (x_k - x_{k-1})}^2
      + \frac{\Lest}{2} \norm*{x_k - x_{k-1}}^2
    }
    \geq
    0,
    \label{eq:potential_lowerbound}\\
    \Phi_0 - f(x_0)
    &=
    \frac{\theta_0^2}{4 \Lest} \norm*{\nabla f(x_0)}^2
    \label{eq:potential_obj_0}
  \end{align}
  since $x_{-1} = x_0$.

  Summing \cref{lem:potential_decrease_iteration} over $k$ and telescoping yields
  \begin{align}
    &\mathInd
    \Phi_k - \Phi_0
    \label{eq:potential_decrease_epoch}\\
    &\leq
    \sum_{i=0}^{k-1}
    \bigg(
      \frac{\theta_{i+1}^2 + \theta_i - 2}{4} \Lest \norm*{x_{i+1} - x_i}^2
      + \frac{7 \theta_i^2}{12} \Mest_i \norm*{x_i - x_{i-1}}^3\\
      &\qquad\qquad
      + \frac{\theta_i^3}{4 \Lest} \Mest_i^2 \norm*{x_i - x_{i-1}}^4
      - \frac{\theta_i^2}{4 \Lest} \norm*{\nabla f(x_i)}^2
    \bigg)\\
    &\leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2
    - \frac{\theta_0^2}{4 \Lest} \norm*{\nabla f(x_0)}^2,
  \end{align}
  where we have used \cref{eq:theta_increase_not_too_fast}, \cref{eq:sum_xk_diff_power34_upperbound}, and $\Mest_i \leq \Mest_{k-1}$.
  Combining \cref{eq:potential_lowerbound,eq:potential_obj_0,eq:potential_decrease_epoch} yields
  \begin{align}
    f(x_k) - f(x_0)
    \leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2.
  \end{align}
  Furthermore, we bound the last two terms as
  \begin{alignat}{2}
    &\mathInd
    \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2\\
    &\leq
    \prn*{
      \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} \sqrt{S_{k-1}}
      + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}
    }
    S_k
    &\quad&\by{$S_{k-1} \leq S_k$}\\
    &\leq
    \prn*{
      \frac{7}{12} \theta_{k-1}^2 (1 - \theta_{k-1})^{5/2}
      + \frac{1}{4} \theta_{k-1}^3 (1 - \theta_{k-1})^5
    }
    \Lest S_k
    &\quad&\by{\cref{eq:condition_continue_k-1}}\\
    &\leq
    \prn*{
      \frac{7}{12} + \frac{1}{4}
    }
    \theta_{k-1}^2 (1 - \theta_{k-1})^2
    \Lest S_k
    &\quad&\by{$0 \leq \theta_{k-1} \leq 1$}\\
    &\leq
    \frac{1}{4}
    \theta_{k-1} (1 - \theta_{k-1})
    \Lest S_k
    &\quad&\by{$0 \leq \theta_{k-1} \leq 1$},
  \end{alignat}
  which results in
  \begin{alignat}{2}
    f(x_k) - f(x_0)
    &\leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{1}{4} \theta_{k-1} (1 - \theta_{k-1}) \Lest S_k\\
    &=
    - \frac{1 - \theta_k}{2} \Lest S_k
    + \frac{(1 - \theta_k)^2 - (1 - \theta_{k-1})^2}{4} \Lest S_k\\
    &\leq
    - \frac{1 - \theta_k}{2} \Lest S_k
    &\quad&\by{\cref{eq:theta_increase_not_too_fast}}
  \end{alignat}
  and concludes the proof.
\end{proof}

\begin{proposition}
  \label{prop:Mk_upperbound}
  Suppose that \cref{asm:hessian_lip} holds.
  Then, the following is true throughout \cref{alg:proposed_agd}: 
  $\Mest_k \leq \max\set{M_0, \Mtrue}$.
\end{proposition}

\begin{lemma}
  \label{lem:grad_interpolation_error}
  Under \cref{asm:hessian_lip}, the following hold for all $k \geq 1$:
  \begin{align}
    &
    \norm*{
      \nabla f(y_k)
      + \theta_k \nabla f(x_{k-1})
      - (1 + \theta_k) \nabla f (x_k)
    }
    \leq
    \theta_k \Mtrue \norm*{x_k - x_{k-1}}^2,
    \label{eq:grad_interpolation_error_Mf}\\
    &
    \norm*{ \nabla f (\bar y_k) }
    \leq
    \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
    + \frac{(k-1) (k+5)^2}{16 Z_k^2} \Mtrue S_k.
    \label{eq:grad_ybark_upperbound_Mf}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{eq:grad_ybark_upperbound_Mf}]
  We have
  \begin{alignat}{2}
    &\mathInd
    p_{k,i} \nabla f(y_i)
    =
    p_{k,i} \Lest (y_i - x_{i+1})\\
    &=
    p_{k,i} \Lest \prn*{
      \theta_i (x_i - x_{i-1})
      - (x_{i+1} - x_i)
    }
    &\quad&\by{\cref{eq:update_xy}}\\
    &=
    \Lest \prn*{
      p_{k,i-1} (x_i - x_{i-1})
      - p_{k,i} (x_{i+1} - x_i)
    }
    &\quad&\by{definition \cref{eq:def_ybark} of $p_{k,i}$}.
  \end{alignat}
  Summing this equality over $i$ yields
  \begin{align}
    \sum_{i=0}^{k-1}
    p_{k,i} \nabla f(y_i)
    =
    - \Lest p_{k,k-1} (x_k - x_{k-1}),
    \label{eq:weighted_average_gradient_equation}
  \end{align}
  where we have used $x_0 = x_{-1}$.
  Now, we obtain
  \begin{alignat}{2}
    &\mathInd
    \norm*{
      \nabla f (\bar y_k)
    }
    \label{eq:norm_grad_ybark_upperbound_pre}\\
    &\leq
    \norm*{
      \sum_{i=0}^{k-1} p_{k,i} \nabla f \prn*{ y_i }
    }
    + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
    &\quad&\by{\cref{lem:gradient_jensen}}\\
    &=
    \Lest p_{k,k-1} \norm*{x_k - x_{k-1}}
    + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
    &\quad&\by{\cref{eq:weighted_average_gradient_equation}}\\
    &\leq
    \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
    + \frac{\Mtrue}{2 Z_k^2} \sum_{0 \leq i < j < k} \norm*{y_i - y_j}^2,
  \end{alignat}
  where the last inequality follows from $p_{k,i} \leq p_{k,k-1} = 1 / Z_k$ for all $0 \leq i < k$.

  Next, we bound the second term on the right-hand side.
  Since for $0 \leq i < j < k$,
  \begin{alignat}{2}
    &\mathInd
    \norm*{y_i - y_j}\\
    &\leq
    \norm*{y_i - x_i}
    + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
    + \norm*{y_j - x_{j-1}}
    &\quad&\by{the triangle inequality}\\
    &=
    \norm*{x_i - x_{i-1}}
    + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
    + 2 \norm*{x_j - x_{j-1}}
    &\quad&\by{\cref{eq:update_xy} and $0 \leq \theta_k \leq 1$}\\
    &\leq
    \prn*{
      1^2 + \sum_{l=i+1}^{j-1} 1^2 + 2^2
    }^{1/2}
    \prn*{
      \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
    }^{1/2}
    &\quad&\by{Cauchy--Schwarz}\\
    &=
    \sqrt{j - i + 4}
    \prn*{
      \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
    }^{1/2},
  \end{alignat}
  we have
  \begin{align}
    \sum_{0 \leq i < j < k}
    \norm*{y_i - y_j}^2
    &\leq
    \sum_{0 \leq i < j < k}
    \sum_{l=i}^j
    (j - i + 4) \norm*{x_l - x_{l-1}}^2\\
    % &=
    % \sum_{0 \leq i \leq l \leq j < k}
    % (j - i + 4) \norm*{x_l - x_{l-1}}^2
    % - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \sum_{l=0}^{k-1}
    \prn*{
      \sum_{i=0}^l
      \sum_{j=l}^{k-1}
      (j - i + 4) 
    }
    \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \frac{k + 7}{2}
    \sum_{l=0}^{k-1}
    (l + 1) (k - l)
    \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &\leq
    \frac{k + 7}{2}
    \sum_{l=0}^{k-1} \frac{(k+1)^2}{4} \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \frac{(k-1) (k+5)^2}{8}
    \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2
    \leq
    \frac{(k-1) (k+5)^2}{8} S_k.
  \end{align}
  Plugging this bound into \cref{eq:norm_grad_ybark_upperbound_pre} concludes the proof.
\end{proof}

\begin{lemma}
  \label{lem:grad_norm_ybar_upperbound}
  Suppose that \cref{asm:gradient_hessian_lip} holds.
  In \cref{alg:proposed_agd}, the following is true when $k \geq 2$:
  \begin{align}
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lmax^2 \Mmax}{M_0^2 k^4}.
    \label{eq:grad_norm_ybar_upperbound}
  \end{align}
  If $M_k$ is computed with \cref{eq:update_Mest} in the algorithm, the above bound is improved to
  \begin{align}
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    4 \Lest \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lmax^2}{M_0 k^4}.
    \label{eq:grad_norm_ybar_upperbound_tight}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{eq:grad_norm_ybar_upperbound}] 
  Note that
  \begin{align}
    &\sum_{i=1}^{k-1}
    \frac{(i-1)(i+5)^2}{16}
    =
    \frac{(k - 2) (k - 1) (k^2 + 13 k + 50)}{64}
    \leq
    \frac{k^3 (k+1)}{24},
    \label{eq:i_cubic_sum}\\
    &\sum_{i=1}^{k-1} Z_i^2
    =
    \sum_{i=1}^{k-1} \prn*{\frac{i+1}{2}}^2
    =
    \frac{(k-1) (2 k^2 + 5 k + 6)}{24}
    \geq 
    \frac{k^2 (k+1)}{12}
    \label{eq:Zi_squared_sum}
  \end{align}
  from \cref{eq:ybar_Zk_alternative} and $k \geq 2$.
  Using \cref{eq:grad_ybark_upperbound_Mf}, we have
  \begin{align}
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    \sum_{i=1}^{k-1}
    Z_i^2
    \norm*{ \nabla f (\bar y_i) }\\
    &\leq
    \sum_{i=1}^{k-1}
    \prn*{
      \Lest Z_i \norm*{x_i - x_{i-1}}
      + \frac{(i-1) (i+5)^2}{16} \Mtrue S_i
    }.
  \end{align}
  Each term on the right-hand side can be bounded as follows:
  \begin{alignat}{2}
    &\sum_{i=1}^{k-1} \Lest Z_i \norm*{x_i - x_{i-1}}
    \leq
    \Lest
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{1/2}
    \sqrt{S_{k-1}}
    &\quad&\by{Cauchy--Schwarz},\\
    &\sum_{i=1}^{k-1}
    \frac{(i-1)(i+5)^2}{16} \Mtrue S_i
    \leq
    \frac{k^3 (k+1)}{24}
    \Mtrue S_{k-1}
    &\quad&\by{\cref{eq:i_cubic_sum}}.
  \end{alignat}
  We thus have
  \begin{alignat}{2}
    &\mathInd
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }\\
    &\leq
    \Lest 
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{-1/2}\!\!
    \sqrt{S_{k-1}}
    + 
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{-1}
    \frac{k^3 (k+1)}{24}
    \Mtrue S_{k-1}\\
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{k}{2}
    \Mtrue S_{k-1}
    &\quad&\by{\cref{eq:Zi_squared_sum}}\\
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{\Lest \Mtrue}{2 \Mest_k} 
    \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{\cref{eq:condition_continue_k-1}}\\
    &\leq
    \frac{\Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{\Lest \Mmax}{2 \Mest_{k-1}} 
    \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{$\Mest_{k-1}, \Mtrue \leq \Mmax$}\\
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}},
  \end{alignat}
  which is the first inequality of the desired result~\cref{eq:grad_norm_ybar_upperbound}.
  The second inequality follows from \cref{eq:condition_continue_k-1}:
  \begin{align}
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lest^2 \Mmax}{M_{k-1}^2 k^4}
    \leq
    \frac{4 \Lmax^2 \Mmax}{M_0 k^4}.
  \end{align}
\end{proof}

\begin{proof}[Proof of \cref{eq:grad_norm_ybar_upperbound_tight}]
  When $M_k$ is computed with \cref{eq:update_Mest}, we have \cref{eq:grad_ybark_upperbound_Mestk}.
  Similarly to the proof of \cref{eq:grad_norm_ybar_upperbound}, using \cref{eq:grad_ybark_upperbound_Mestk} instead of \cref{eq:grad_ybark_upperbound_Mf} yields
  \begin{alignat}{2}
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{k}{2} \Mest_{k-1} S_{k-1}.
  \end{alignat}
  The right-hand side is bounded as
  \begin{alignat}{2}
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{k}{2} \Mest_{k-1} S_{k-1}
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{\Lest}{2} \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{\cref{eq:condition_continue_k-1}}\\
    &\leq
    4 \Lest
    \sqrt{\frac{S_{k-1}}{k^3}},
  \end{alignat}
  which implies the first inequality in \cref{eq:grad_norm_ybar_upperbound_tight}.
  The second inequality is obtained similarly to the second inequality of \cref{eq:grad_norm_ybar_upperbound}.
\end{proof}

\begin{proof}[Proof of bound \cref{eq:complexity_bound}]
  We count the number of iterations of \cref{alg:proposed_agd} separately for three types of epoch:
  \begin{itemize}
    \item 
    successful epoch: an epoch that does not find an $\epsilon$-stationary point and ends at Line \ref{alg-line-agd:restart_successful} with the descent condition~\cref{eq:descent_condition} satisfied,
    \item
    unsuccessful epoch: an epoch that does not find an $\epsilon$-stationary point and ends at Line \ref{alg-line-agd:restart_unsuccessful} with the descent condition~\cref{eq:descent_condition} unsatisfied,
    \item
    last epoch: the epoch that finds an $\epsilon$-stationary point.
  \end{itemize}

  \paragraph{Successful epochs}
  Let us focus on a successful epoch.
  Let $k$ be the iteration number of the epoch.
  It follows that 
  \begin{align}
    (k+1)^5
    \Mest_k^2 S_k
    &>
    \Lest^2.
    \label{eq:restart_condition_k}
  \end{align}
  When $k \geq 2$, we have
  \begin{alignat}{2}
    \epsilon
    &<
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\quad&\text{(since this epoch does not find an $\epsilon$-stationary point)}\\
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{\cref{eq:grad_norm_ybar_upperbound}}\\
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_0} \sqrt{\frac{S_k}{k^3}}
    &\quad&\by{$M_{k-1} \geq M_0$ and $S_k \geq S_{k-1}$},
  \end{alignat}
  and hence 
  \begin{align}
    S_k > \prn*{\frac{\epsilon \Mest_0}{4 \Lest \Mmax}}^2 k^3.
    \label{eq:Sk_lowerbound}
  \end{align}
  When $k = 1$, we also have \cref{eq:Sk_lowerbound}, as follows:
  \begin{align}
    S_k
    =
    \norm*{x_1 - x_0}^2
    =
    \frac{1}{\Lest^2} \norm*{\nabla f(x_0)}^2
    =
    \frac{1}{\Lest^2} \norm*{\nabla f(\bar y_1)}^2
    >
    \frac{\epsilon^2}{\Lest^2}
    \geq
    \prn*{\frac{\epsilon \Mest_0}{4 \Lest \Mmax}}^2 k^3.
  \end{align}
  Combining \cref{eq:Sk_lowerbound,eq:restart_condition_k} yields
  \begin{align}
    S_k
    =
    S_k^{7/8}
    S_k^{1/8}
    &\geq
    \prn[\bigg]{\prn*{\frac{\epsilon \Mest_0}{4 \Lest \Mmax}}^2 k^3}^{7/8}
    \prn*{\frac{\Lest^2}{\Mest_k^2 (k+1)^5}}^{1/8}\\
    &=
    \frac{(\epsilon / 4)^{7/4}}{\Lest^{3/2}}
    \frac{M_0^{7/4}}{\Mmax^{7/4} \Mest_k^{1/4}}
    \frac{k^{21/8}}{(k+1)^{5/8}}
    \geq
    \frac{(\epsilon / 4)^{7/4}}{\Lest^{3/2}}
    \frac{M_0^{7/4}}{\Mmax^2}
    \frac{k^{21/8}}{(k+1)^{5/8}}.
  \end{align}
  Plugging this bound into condition \cref{eq:descent_condition}, we obtain
  \begin{align}
    f(x_0) - f(x_k)
    \geq
    \frac{\Lest S_k}{2 (k+1)}
    &\geq
    \frac{(\epsilon / 4)^{7/4}}{\Lest^{1/2}}
    \frac{M_0^{7/4}}{\Mmax^2}
    \prn*{\frac{k}{k+1}}^{13/8}
    \frac{k}{2}\\
    &\geq
    \frac{(\epsilon / 4)^{7/4}}{\Lmax^{1/2}}
    \frac{M_0^{7/4}}{\Mmax^2}
    \prn*{\frac{1}{2}}^{13/8}
    \frac{k}{2}
    \geq
    \frac{\epsilon^{7/4} M_0^{7/4}}{\Lmax^{1/2} \Mmax^2}
    \frac{k}{70},
  \end{align}
  and thus
  \begin{align}
    k
    \leq
    70
    \frac{\Lmax^{1/2} \Mmax^2}{\epsilon^{7/4} M_0^{7/4}}
    \prn*{f(x_0) - f(x_k)}.
  \end{align}
  Summing this bound over all successful epochs leads to the conclusion that the total iteration number of successful epochs is at most
  \begin{align}
    70 \frac{\Lmax^{1/2} \Mmax^2 \Delta}{\epsilon^{7/4} M_0^{7/4}}.
    \label{eq:Ksuc_upperbound}
  \end{align}
  For later use, we will also evaluate the number of successful epochs.
  Combining \cref{eq:Sk_lowerbound,eq:restart_condition_k} also yields
  \begin{align}
    S_k
    =
    S_k^{3/4}
    S_k^{1/4}
    &\geq
    \prn[\bigg]{ \prn*{\frac{\epsilon \Mest_0}{4 \Lest \Mmax}}^2 k^3 }^{3/4}
    \prn*{\frac{\Lest^2}{\Mest_k^2 (k+1)^5}}^{1/4}\\
    &=
    \frac{(\epsilon / 4)^{3/2}}{\Lest}
    \frac{\Mest_0^{3/2}}{\Mmax^{3/2} \Mest_k^{1/2}}
    \frac{k^{9/4}}{(k+1)^{5/4}}
    \geq
    \frac{(\epsilon / 4)^{3/2}}{\Lest}
    \frac{\Mest_0^{3/2}}{\Mmax^2}
    \frac{k^{9/4}}{(k+1)^{5/4}}.
  \end{align}
  Plugging this bound into condition \cref{eq:descent_condition} gives
  \begin{align}
    f(x_0) - f(x_k)
    \geq
    \frac{\Lest S_k}{2 (k+1)}
    &\geq
    \frac{(\epsilon / 4)^{3/2}}{2}
    \frac{\Mest_0^{3/2}}{\Mmax^2}
    \prn*{\frac{k}{k+1}}^{9/4}\\
    &\geq
    \frac{(\epsilon / 4)^{3/2}}{2}
    \frac{\Mest_0^{3/2}}{\Mmax^2}
    \prn*{\frac{1}{2}}^{9/4}
    =
    \frac{\epsilon^{3/2} \Mest_0^{3/2}}{2^{25/4} \Mmax^2}.
  \end{align}
  Thus, we can deduce that the number $N_{\mathrm{suc}}$ of successful epochs satisfies
  \begin{align}
    N_{\mathrm{suc}}
    \leq
    2^{25/4}
    \frac{\Mmax^2 \Delta}{\epsilon^{3/2} \Mest_0^{3/2}}.
    \label{eq:Nsuc_upperbound}
  \end{align}

  \paragraph{Other epochs}
  We deduce from \cref{eq:grad_norm_ybar_upperbound} that the number of iterations for each epoch is at most
  \begin{align}
    \prn*{
      \frac{4 \Lmax^2 \Mmax}{\epsilon M_0^2}
    }^{1/4}.
  \end{align}
  Let $N_{\mathrm{unsuc}}$ be the number of unsuccessful epochs.
  We then have
  \begin{align}
    \Linit
    \beta^{N_{\mathrm{suc}}}
    \alpha^{N_{\mathrm{unsuc}}}
    \leq
    \Lmax,
  \end{align}
  and hence
  \begin{align}
    N_{\mathrm{unsuc}}
    \leq
    c_1 N_{\mathrm{suc}} + c_2,
    \label{eq:Nunsuc_upperbound}
  \end{align}
  where $c_1$ and $c_2$ are defined by \cref{eq:def_c1_c2}.
  The total iteration number of unsuccessful and last epochs is at most
  \begin{alignat}{2}
    &\mathInd
    (N_{\mathrm{unsuc}} + 1)
    \prn*{ \frac{4 \Lmax^2 \Mmax}{\epsilon M_0^2} }^{1/4}\\
    &\leq
    \prn*{ c_1 N_{\mathrm{suc}} + c_2 + 1 }
    \prn*{ \frac{4 \Lmax^2 \Mmax}{\epsilon M_0^2} }^{1/4}
    &\quad&\by{\cref{eq:Nunsuc_upperbound}}\\
    &\leq
    2^{27/4} c_1
    \frac{\Lmax^{1/2} \Mmax^{9/4} \Delta}{\epsilon^{7/4} \Mest_0^2}
    + 2^{1/2} (c_2 + 1) \frac{\Lmax^{1/2} \Mmax^{1/4}}{\epsilon^{1/4} M_0^{1/2}}
    &\quad&\by{\cref{eq:Nsuc_upperbound}}\\
    &\leq
    108 c_1
    \frac{\Lmax^{1/2} \Mmax^{9/4} \Delta}{\epsilon^{7/4} \Mest_0^2}
    + 2 (c_2 + 1) \frac{\Lmax^{1/2} \Mmax^{1/4}}{\epsilon^{1/4} M_0^{1/2}}.
  \end{alignat}
  Putting this bound together with \cref{eq:Ksuc_upperbound} concludes the proof.
\end{proof}

\begin{proof}[Proof of bound \cref{eq:complexity_bound_tight}]
  The proof is similar to \cref{eq:complexity_bound} through the evaluation of the total iteration number of successful, unsuccessful, and last epochs.

  \paragraph{Successful epochs}
  Let us focus on a successful epoch.
  Let $k$ be the iteration number of the epoch.
  As a counterpart of \cref{eq:Sk_lowerbound}, we can obtain 
  \begin{align}
    S_k > \prn*{\frac{\epsilon}{4 \Lest}}^2 k^3
    \label{eq:Sk_lowerbound_tight}
  \end{align}
  from \cref{eq:grad_norm_ybar_upperbound_tight}.
  Combining \cref{eq:Sk_lowerbound_tight,eq:restart_condition_k} yields
  \begin{align}
    S_k
    &=
    S_k^{7/8}
    S_k^{1/8}
    \geq
    \prn*{\prn*{\frac{\epsilon}{4 \Lest}}^2 k^3}^{7/8}
    \prn*{\frac{\Lest^2}{\Mest_k^2 (k+1)^5}}^{1/8}
    =
    \frac{(\epsilon / 4)^{7/4}}{\Lest^{3/2} \Mest_k^{1/4}}
    \frac{k^{21/8}}{(k+1)^{5/8}}.
  \end{align}
  Plugging this bound into condition \cref{eq:descent_condition}, we obtain
  \begin{align}
    f(x_0) - f(x_k)
    \geq
    \frac{\Lest S_k}{2 (k+1)}
    &\geq
    \frac{(\epsilon / 4)^{7/4}}{\Lest^{1/2} \Mest_k^{1/4}}
    \prn*{\frac{k}{k+1}}^{13/8}
    \frac{k}{2}\\
    &\geq
    \frac{(\epsilon / 4)^{7/4}}{\Lmax^{1/2} \Mmax^{1/4}}
    \prn*{\frac{1}{2}}^{13/8}
    \frac{k}{2}
    \geq
    \frac{\epsilon^{7/4}}{\Lmax^{1/2} \Mmax^{1/4}}
    \frac{k}{70}.
  \end{align}
  Hence, as in the proof of \cref{eq:complexity_bound}, the total iteration number of all successful epochs is at most
  \begin{align}
    70
    \frac{\Lmax^{1/2} \Mmax^{1/4} \Delta}{\epsilon^{7/4}}.
    \label{eq:Ksuc_upperbound_tight}
  \end{align}

  \paragraph{Other epochs}
  We deduce from \cref{eq:grad_norm_ybar_upperbound_tight} that the iteration number of each epoch is at most $\prn[\big]{ \frac{4 \Lmax^2}{M_0 \epsilon} }^{1/4}$.
  In addition, unsuccessful epochs occur only at most $c_2$ times when $\beta = 1$, where $c_2$ is defined by \cref{eq:def_c1_c2}.
  Thus, the total iteration number of unsuccessful and last epochs is at most
  \begin{align}
    \prn*{
      c_2 + 1
    }
    \prn*{
      \frac{4 \Lmax^2}{M_0 \epsilon}
    }^{1/4}
    \leq
    2 (c_2 + 1) \frac{\Lmax^{1/2}}{M_0^{1/4} \epsilon^{1/4}}.
  \end{align}
  Putting this bound together with \cref{eq:Ksuc_upperbound_tight} concludes the proof.
\end{proof}

source_units.raw_tex:
This paper studies general nonconvex optimization problems:
\begin{align}
  \min_{x \in \R^d} \ 
  f(x),
\end{align}
where $f: \R^d \to \R$ is bounded below (i.e., $\inf_{x \in \R^d} f(x) > - \infty$) and satisfies the following Lipschitz assumption.

\begin{assumption}
  \label{asm:gradient_hessian_lip}
  Let $\Ltrue, \Mtrue > 0$ be constants.
  \begin{enuminasm}
    \item
    \label{asm:gradient_lip}
    $\norm*{\nabla f(x) - \nabla f(y)} \leq \Ltrue \norm*{x - y}$ for all $x, y \in \R^d$,

    \item
    \label{asm:hessian_lip}
    $\norm*{\nabla^2 f(x) - \nabla^2 f(y)} \leq \Mtrue \norm*{x - y}$ for all $x, y \in \R^d$.
  \end{enuminasm}
\end{assumption}

\paragraph{Notation}
For vectors $a, b \in \R^d$, let $\inner{a}{b}$ denote the dot product and $\norm{a}$ denote the Euclidean norm.
For a matrix $A \in \R^{m \times n}$, let $\norm{A}$ denote the operator norm, or equivalently the largest singular value.

\begin{lemma}
  \label{lem:eq:property_gradlip_obj}
  Under \cref{asm:gradient_lip}, the following holds for any $x, y \in \R^d$:
  \begin{align}
    f(x) - f(y)
    &\leq
    \inner*{\nabla f(y)}{x - y}
    + \frac{\Ltrue}{2} \norm*{x - y}^2.
  \end{align}
\end{lemma}

\paragraph{Solution update (Lines \ref{alg-line-agd:update_x} and \ref{alg-line-agd:update_y})}
With an estimate $L$ of the Lipschitz constant $L_f$, AGD defines solution sequences $(x_k)$ and $(y_k)$ as follows:
$y_0 = x_0$ and
\begin{align}
  % \left\{
  \begin{aligned}
    x_k
    &=
    y_{k-1} - \frac{1}{L} \nabla f(y_{k-1}),\\
    y_k
    &=
    x_k + \theta_k (x_k - x_{k-1})
  \end{aligned}
  % \right.
  \label{eq:update_xy}
\end{align}
for $k \geq 1$, where $0 \leq \theta_k \leq 1$ is the acceleration parameter.
Let $x_{-1} \coloneqq x_0$ for convenience, which makes the lower equation of \cref{eq:update_xy} valid for $k = 0$.
Setting a suitable value of $\theta_k$ is crucial for deriving an improved complexity bound over that of gradient descent.

In particular, we propose to set
\begin{align}
  \theta_k = \frac{k}{k+1}
  \label{eq:def_theta_k}
\end{align}
for $k \geq 1$.

\begin{algorithm}[t]
  \caption{Proposed AGD with restart~\label{alg:proposed_agd}} 
  \begin{algorithmic}[1]
    \Require{%
      \pbox[t]{40em}{
        $x_{\mathrm{init}} \in \R^d$;
        $\Linit, M_0 > 0$;
        $\alpha > 1$;
        $0 < \beta \leq 1$\\
        Recommended: $(\Linit, M_0, \alpha, \beta) = (10^{-3}, 10^{-16}, 2, 0.9)$
      }
    }
    \State{%
      $(x_0, y_0) \gets (x_{\mathrm{init}}, x_{\mathrm{init}})$,
      $\Lest \gets \Linit$,
      $k \gets 0$,
      $K \gets 0$
    }
    \Repeat
      \State{%
        $k \gets k + 1$,
        $K \gets K + 1$
      }
      \State $x_k \gets y_{k-1} - \frac{1}{\Lest} \nabla f(y_{k-1})$
      \label{alg-line-agd:update_x}
      \State $y_k \gets x_k + \frac{k}{k+1} (x_k - x_{k-1})$
      \label{alg-line-agd:update_y}

      \If{$f(x_k) > f(x_0) - \frac{\Lest S_k}{2 (k+1)}$}
      \Comment{$S_k \coloneqq \sum_{i=1}^k \norm*{x_i - x_{i-1}}^2$}
      \label{alg-line-agd:check_decrease}
        \State{%
          $(x_0, y_0) \gets (x_{k-1}, x_{k-1})$,
          $\Lest \gets \alpha \Lest$,
          $k \gets 0$
        }
        \label{alg-line-agd:restart_unsuccessful}
      \ElsIf{$(k+1)^5 \Mest_k^2 S_k > \Lest^2$}
      \Comment{$\Mest_k$ is defined by \cref{eq:update_Mest_practical} or \cref{eq:update_Mest}}
      \label{alg-line-agd:check_large_Sk}
        \State{%
          $(x_0, y_0) \gets (x_k, x_k)$,
          $\Lest \gets \beta \Lest$,
          $k \gets 0$
        }
        \label{alg-line-agd:restart_successful}
      \EndIf
    \Until{convergence}
    \State \Return averaged solution $\bar y_k$ defined by \eqref{eq:def_ybark}
  \end{algorithmic}
\end{algorithm}

\paragraph{Averaged solution}
\label{sec:averaged_solution}
Our AGD guarantees that the gradient norm is small at a weighted average $\bar y_k$ of the solutions $y_0,\dots,y_{k-1}$.
The averaged solution $\bar y_k$ is defined by
\begin{align}
  \bar y_k
  \coloneqq
  \sum_{i=0}^{k-1} p_{k,i} y_i,
  \quad\text{where}\quad
  p_{k,i}
  \coloneqq
  \frac{1}{Z_k} \prod_{j=i+1}^{k-1} \theta_j,
  \quad
  Z_k
  \coloneqq
  \sum_{i=0}^{k-1} \prod_{j=i+1}^{k-1} \theta_j.
  \label{eq:def_ybark}
\end{align}

Note that it is unnecessary to keep all $y_0,\dots,y_{k-1}$ in memory to compute $\bar y_k$ because $Z_k$ and $\bar y_k$ satisfy a simple recursion:
\begin{align}
  Z_{k+1}
  &=
  1 + \theta_k Z_k,\quad
  \bar y_{k+1}
  =
  \frac{1}{Z_{k+1}} \prn*{y_k + \theta_k Z_k \bar y_k},
\end{align}
which maintains the computational efficiency of the algorithm.

Given \cref{eq:def_theta_k}, there is another form:
\begin{align}
  \bar y_k
  =
  \frac{2}{k (k + 1)}
  \sum_{i=0}^{k-1} (i + 1) y_i,\quad
  Z_k
  =
  \frac{k + 1}{2},
  \label{eq:ybar_Zk_alternative}
\end{align}
and this simplification of $\bar y_k$ and $Z_k$ is one of the aims of setting $\theta_k$ as in \cref{eq:def_theta_k}.

\paragraph{Estimate of Hessian's Lipschitz constant}
The estimate $M_k$ for the Hessian is updated at each iteration, unlike $L$ for the gradient.
Our complexity analysis requires three inequalities on $M_k$: $M_{k-1} \leq M_k$ and
\begin{align}
  &
  f(y_k) - f(x_k)
  \leq
  \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
  + \frac{\Mest_k}{12} \norm*{y_k - x_k}^3,
  \label{eq:fy_fx_diff_upperbound_Mestk}\\
  &
  \norm*{
    \nabla f(y_k)
    + \theta_k \nabla f(x_{k-1})
    - (1 + \theta_k) \nabla f (x_k)
  }
  \leq
  \theta_k \Mest_k \norm*{x_k - x_{k-1}}^2.
  \label{eq:grad_interpolation_error_Mestk}
\end{align}

Finding the smallest $M_k$ that satisfies these inequalities is desirable, and fortunately, it is straightforward,
\begin{align}
  \label{eq:update_Mest_practical}
  \Mest_k
  =
  \max \bigg\{
    \Mest_{k-1},\ 
    &
    \frac{
      12
      \prn*{
        f(y_k) - f(x_k) 
        - \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
      }
    }{\norm*{y_k - x_k}^3},\\
    &
    \frac{
      \norm*{
        \nabla f(y_k)
        + \theta_k \nabla f(x_{k-1})
        - (1 + \theta_k) \nabla f (x_k)
      }
    }{\theta_k \norm*{x_k - x_{k-1}}^2}
  \bigg\}
\end{align}
because $x_k$, $y_k$, and $\theta_k$ are already in hand.
In other words, our $\theta_k$ in \cref{eq:def_theta_k} does not depend on the estimate $M_k$ of $M_f$, which facilitates computation of $M_k$.
Thus, we can estimate $M_f$ without backtracking, thereby simplifying the algorithm and improving its efficiency.

Instead of \cref{eq:update_Mest_practical}, we can use
\begin{align}
  \label{eq:update_Mest}
  \Mest_k
  =
  \max \bigg\{
    \Mest_{k-1},\ 
    &
    \frac{
      12
      \prn*{
        f(y_k) - f(x_k) 
        - \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
      }
    }{\norm*{y_k - x_k}^3}
    ,\\
    &
    \frac{
      \norm*{
        \nabla f(y_k)
        + \theta_k \nabla f(x_{k-1})
        - (1 + \theta_k) \nabla f (x_k)
      }
    }{\theta_k \norm*{x_k - x_{k-1}}^2},\\
    &
    \frac{
      16
      \prn*{
        Z_k^2 \norm*{ \nabla f (\bar y_k) }
        - Z_k \Lest \norm*{x_k - x_{k-1}}
      }
    }{(k-1) (k+5)^2 S_k}
  \bigg\}.
\end{align}
in the algorithm.\footnote{
  For $k = 1$, \Cref{eq:update_Mest} takes the form $M_1 = \max \set{M_0, \ast, \ast, \frac{0}{0}}$, which should be treated as $M_1 = \max \set{M_0, \ast, \ast}$.
}

This replacement ensures that
\begin{align}
  \norm*{ \nabla f (\bar y_k) }
  \leq
  \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
  + \frac{(k-1) (k+5)^2}{16 Z_k^2} \Mest_k S_k
  \label{eq:grad_ybark_upperbound_Mestk}
\end{align}
and will lead to a smaller complexity bound with lessened dependence on $M_0$ and $M_f$, as will be confirmed later in \cref{thm:complexity}.

To obtain the descent condition~\cref{eq:descent_condition}, we first evaluate the decrease for one iteration.
However, a common difficulty arises when analyzing AGD: the objective function value does not necessarily decrease monotonically.
To deal with the problem, we introduce a potential function related to $f(x_k)$ and show that it is \emph{nearly} decreasing.
The potential function $\Phi_k$ is defined by
\begin{align}
  \Phi_k
  \coloneqq
  f(x_k)
  + \frac{\theta_k^2}{2} \prn*{
    \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
    + \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1})}^2
    + \Lest \norm*{x_k - x_{k-1}}^2
  },
  \label{eq:def_potential}
\end{align}
inspired by \cref{eq:hint_potential} used in the proof.
The value $\Phi_k$ decreases when $\norm*{x_k - x_{k-1}}$ is small enough as the following lemma shows.

To evaluate the terms of $\norm*{x_k - x_{k-1}}^3$ and $\norm*{x_k - x_{k-1}}^4$ in \cref{lem:potential_decrease_iteration} in these calculations, we use 
\begin{align}
  \Mest_{k-1}^2 S_{k-1}
  \leq
  \Lest^2 (1 - \theta_{k-1})^5
  =
  \frac{\Lest^2}{k^5},
  \label{eq:condition_continue_k-1}
\end{align}
which follows from the fact that the epoch did not end at iteration $k-1$.

Now, we prove \cref{lem:potential_decrease_iteration} and use it to prove \cref{lem:decrease_epoch}.
The following proofs do not use the specific form \cref{eq:def_theta_k} of $\theta_k$ but rather a more general condition on $\theta_k$,
\begin{align}
  \theta_{k+1}^2 \leq \theta_k \leq \theta_{k+1},
  \label{eq:theta_increase_not_too_fast}
\end{align}
which is easily verified for all $k \geq 0$ under $\theta_0 \coloneqq \theta_1^2$ and \cref{eq:def_theta_k} for $k \geq 1$.

\subsection{Upper bound on gradient norm}
Let $\Lmax$ and $\Mmax$ be the upper bounds on $L$ and $M_k$ given in \cref{prop:L_upperbound,prop:Mk_upperbound}: $\Lmax \coloneqq \max\set{\Linit, \alpha \Ltrue}$ and $\Mmax \coloneqq \max\set{M_0, \Mtrue}$.
The following lemma provides upper bounds on the gradient norm.

\begin{lemma}[Jensen-type inequality for gradients]
  \label{lem:gradient_jensen}
  Under \cref{asm:hessian_lip}, the following holds for any $z_1, \dots, z_n \in \R^d$ and $\lambda_1,\dots,\lambda_n \geq 0$ such that $\sum_{i=1}^n \lambda_i = 1$:
  \begin{align}
    \norm*{
      \nabla f \prn*{ \sum_{i=1}^n \lambda_i z_i }
      - \sum_{i=1}^n \lambda_i \nabla f \prn*{ z_i }
    }
    \leq
    \frac{\Mtrue}{2} \sum_{1 \leq i < j \leq n} \lambda_i \lambda_j \norm*{z_i - z_j}^2.
  \end{align}
\end{lemma}

\begin{lemma}[Error bound for trapezoidal rule]
  \label{lem:trapezoidal_rule_error}
  Under \cref{asm:hessian_lip}, the following holds for any $x, y \in \R^d$:
  \begin{align}
    f(x) - f(y)
    &\leq
    \frac{1}{2} \inner*{\nabla f(x) + \nabla f(y)}{x - y}
    + \frac{\Mtrue}{12} \norm*{x - y}^3.
  \end{align}
\end{lemma}

\begin{proposition}
  \label{prop:L_upperbound}
  Suppose that \cref{asm:gradient_lip} holds.
  Then, the following is true throughout \cref{alg:proposed_agd}: $\Lest \leq \max\set{\Linit, \alpha \Ltrue}$.
\end{proposition}

\begin{lemma}
  \label{lem:decrease_epoch}
  Suppose that \cref{asm:gradient_lip} holds.
  During epochs with $\Lest \geq \Ltrue$, condition~\cref{eq:descent_condition} always holds.
\end{lemma}

\begin{lemma}
  \label{lem:potential_decrease_iteration}
  Under \cref{asm:gradient_lip} and $\Lest \geq \Ltrue$, the following holds for all $k \geq 0$:
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 + \theta_k - 2}{4} \Lest \norm*{x_{k+1} - x_k}^2
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3\\
    &\quad
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
    \label{eq:potential_decrease_iteration}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{lem:potential_decrease_iteration}]
  In the proof, let
  \begin{align}
    P_k
    &\coloneqq
    \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
  \end{align}
  to simplify the notation.
  From \cref{lem:eq:property_gradlip_obj,eq:update_xy}, we have
  \begin{align}
    f(x_{k+1}) - f(y_k)
    &\leq
    \inner*{\nabla f(y_k)}{x_{k+1} - y_k}
    + \frac{\Lest}{2} \norm*{x_{k+1} - y_k}^2
    = 
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2.
  \end{align}
  Summing this bound and \cref{eq:fy_fx_diff_upperbound_Mestk} yields
  \begin{alignat}{2}
    &\mathInd
    f(x_{k+1}) - f(x_k)
    \label{eq:descent_f_first}\\
    &\leq
    \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
    + \frac{\Mest_k}{12} \norm*{y_k - x_k}^3
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2\\
    &\leq
    \frac{1}{2} \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}
    + \frac{\theta_k^2 \Mest_k}{12} \norm*{x_k - x_{k-1}}^3
    - \frac{1}{2 \Lest} \norm*{\nabla f(y_k)}^2,
  \end{alignat}
  where the last inequality uses \cref{eq:update_xy} and $0 \leq \theta_k \leq 1$.
  To evaluate the first term on the right-hand side, we decompose it into four terms:
  \begin{align}
    &\mathInd
    \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}\\
    &=
    \underbrace{2 \inner*{\nabla f(y_k)}{y_k - x_k}}_{\text{(A)}}
    {}+{} \underbrace{\theta_k \inner*{\nabla f(x_{k-1})}{y_k - x_k}}_{\text{(B)}}\\[-0.8\baselineskip]
    &\quad
    - \underbrace{\theta_k \inner*{\nabla f(x_k)}{y_k - x_k}}_{\text{(C)}}
    {}-{} \underbrace{
        \inner*{
        \nabla f(y_k)
        + \theta_k \nabla f(x_{k-1})
        - (1 + \theta_k) \nabla f (x_k)
      }{y_k - x_k}
    }_{\text{(D)}}.
  \end{align}
  Each term can be evaluated as
  \begin{alignat}{2}
    \text{(A)}
    &=
    \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
    + \Lest \norm*{y_k - x_k}^2
    - \Lest \norm*{(y_k - x_k) - \frac{1}{\Lest} \nabla f(y_k)}^2\\
    &=
    \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
    + \theta_k^2 \Lest \norm*{x_k - x_{k-1}}^2
    - \Lest \norm*{x_{k+1} - x_k}^2
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(B)}
    &=
    \theta_k^2 \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
    =
    \theta_k^2 P_k
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(C)}
    &=
    - \theta_k P_{k+1}
    + \theta_k \inner*{\nabla f(x_k)}{x_{k+1} - y_k}\\
    &=
    - \theta_k P_{k+1}
    - \frac{\theta_k}{\Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}
    &\quad&\by{\cref{eq:update_xy}},\\
    \text{(D)}
    &\leq
    \theta_k \Mest_k \norm*{x_k - x_{k-1}}^2 \norm*{y_k - x_k}
    &\quad&\by{\cref{eq:grad_interpolation_error_Mestk}}\\
    &=
    \theta_k^2 \Mest_k \norm*{x_k - x_{k-1}}^3
    &\quad&\by{\cref{eq:update_xy}}.
  \end{alignat}
  Plugging the evaluations into \cref{eq:descent_f_first} results in
  \begin{align}
    % &\mathInd
    f(x_{k+1}) - f(x_k)
    \label{eq:descent_f_second}
    &\leq
    \frac{\theta_k^2 \Lest}{2} \norm*{x_k - x_{k-1}}^2
    - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2
    + \frac{\theta_k^2}{2} P_k
    - \frac{\theta_k}{2} P_{k+1}\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    - \frac{\theta_k}{2 \Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}.
  \end{align}

  Next, to bound the last term on the right-hand side, we use the following inequality from \cref{eq:grad_interpolation_error_Mestk}:
  \begin{align}
    \norm*{
      \nabla f(y_k)
      - (1 + \theta_k) \nabla f (x_k)
    }
    &\leq
    \theta_k \norm*{ \nabla f(x_{k-1})}
    + 
    \theta_k \Mest_k
    \norm*{x_k - x_{k-1}}^2.
  \end{align}
  We square both sides as
  \begin{alignat}{2}
    &\mathInd
    \norm*{
      \nabla f(y_k)
      - (1 + \theta_k) \nabla f (x_k)
    }^2\\
    &=
    \norm*{\nabla f(y_k)}^2
    + (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
    - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}\\
    &\geq
    (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
    - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}
  \end{alignat}
  and
  \begin{alignat}{2}
    \theta_k^2 \prn*{
      \norm*{ \nabla f(x_{k-1})}
      + \Mest_k \norm*{x_k - x_{k-1}}^2
    }^2
    &\leq
    \theta_k (1 + \theta_k) \norm*{ \nabla f(x_{k-1})}^2\\
    &\quad
    + \theta_k^2 (1 + \theta_k) \Mest_k^2 \norm*{x_k - x_{k-1}}^4,
  \end{alignat}
  where we have used $(a + b)^2 \leq (1 + 1/\theta) a^2 + (1 + \theta) b^2$ for $a, b, \theta > 0$.
  Rearranging the terms yields
  \[
  % \begin{align}
    - \inner*{\nabla f (x_k)}{\nabla f(y_k)}
    \leq
    \frac{\theta_k}{2} \norm*{ \nabla f(x_{k-1})}^2
    - \frac{1 + \theta_k}{2} \norm*{\nabla f (x_k)}^2
    + \frac{\theta_k^2}{2} \Mest_k^2 \norm*{x_k - x_{k-1}}^4.
  % \end{align}
  \]
  Plugging this bound into \cref{eq:descent_f_second} results in
  \begin{align}
    \label{eq:hint_potential}
    &\mathInd
    f(x_{k+1}) - f(x_k)\\
    &\leq
    \frac{\theta_k^2}{2} \prn*{
      P_k
      + \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1})}^2
      + \Lest \norm*{x_k - x_{k-1}}^2
    }\\
    &\quad
    -
    \frac{\theta_k}{2} \prn*{
      P_{k+1} + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    }
    - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
  This inequality can be rewritten with the potential function $\Phi_k$ defined in \cref{eq:def_potential} as
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 - \theta_k}{2}
    \prn*{
      P_{k+1}
      + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    }
    + \frac{\theta_{k+1}^2 - 1}{2} \Lest \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
  Finally, using $\theta_{k+1}^2 - \theta_k \leq 0$ from \cref{eq:theta_increase_not_too_fast} and
  \begin{align}
    - P_{k+1}
    =
    - \inner*{\nabla f(x_k)}{x_{k+1} - x_k}
    \leq
    \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
    + \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2
  \end{align}
  from Young's inequality ($\abs{\inner*{a}{b}} \leq \frac{1}{2} \norm*{a}^2 + \frac{1}{2} \norm*{b}^2$) yields the desired result as
  \begin{align}
    \Phi_{k+1} - \Phi_k
    &\leq
    \frac{\theta_{k+1}^2 - \theta_k}{2} \prn*{- \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2}
    + \frac{\theta_{k+1}^2 - 1}{2} \Lest \norm*{x_{k+1} - x_k}^2\\
    &\quad
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2\\
    &=
    \frac{\theta_{k+1}^2 + \theta_k - 2}{4} \Lest \norm*{x_{k+1} - x_k}^2
    + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3\\
    &\quad
    + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
    - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
  \end{align}
\end{proof}

To evaluate the first term on the right-hand side, we decompose it into four terms:
\begin{align}
  &\mathInd
  \inner*{\nabla f(y_k) + \nabla f(x_k)}{y_k - x_k}\\
  &=
  \underbrace{2 \inner*{\nabla f(y_k)}{y_k - x_k}}_{\text{(A)}}
  {}+{} \underbrace{\theta_k \inner*{\nabla f(x_{k-1})}{y_k - x_k}}_{\text{(B)}}\\[-0.8\baselineskip]
  &\quad
  - \underbrace{\theta_k \inner*{\nabla f(x_k)}{y_k - x_k}}_{\text{(C)}}
  {}-{} \underbrace{
      \inner*{
      \nabla f(y_k)
      + \theta_k \nabla f(x_{k-1})
      - (1 + \theta_k) \nabla f (x_k)
    }{y_k - x_k}
  }_{\text{(D)}}.
\end{align}
Each term can be evaluated as
\begin{alignat}{2}
  \text{(A)}
  &=
  \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
  + \Lest \norm*{y_k - x_k}^2
  - \Lest \norm*{(y_k - x_k) - \frac{1}{\Lest} \nabla f(y_k)}^2\\
  &=
  \frac{1}{\Lest} \norm*{\nabla f(y_k)}^2
  + \theta_k^2 \Lest \norm*{x_k - x_{k-1}}^2
  - \Lest \norm*{x_{k+1} - x_k}^2
  &\quad&\by{\cref{eq:update_xy}},\\
  \text{(B)}
  &=
  \theta_k^2 \inner*{\nabla f(x_{k-1})}{x_k - x_{k-1}}
  =
  \theta_k^2 P_k
  &\quad&\by{\cref{eq:update_xy}},\\
  \text{(C)}
  &=
  - \theta_k P_{k+1}
  + \theta_k \inner*{\nabla f(x_k)}{x_{k+1} - y_k}\\
  &=
  - \theta_k P_{k+1}
  - \frac{\theta_k}{\Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}
  &\quad&\by{\cref{eq:update_xy}},\\
  \text{(D)}
  &\leq
  \theta_k \Mest_k \norm*{x_k - x_{k-1}}^2 \norm*{y_k - x_k}
  &\quad&\by{\cref{eq:grad_interpolation_error_Mestk}}\\
  &=
  \theta_k^2 \Mest_k \norm*{x_k - x_{k-1}}^3
  &\quad&\by{\cref{eq:update_xy}}.
\end{alignat}
Plugging the evaluations into \cref{eq:descent_f_first} results in
\begin{align}
  % &\mathInd
  f(x_{k+1}) - f(x_k)
  \label{eq:descent_f_second}
  &\leq
  \frac{\theta_k^2 \Lest}{2} \norm*{x_k - x_{k-1}}^2
  - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2
  + \frac{\theta_k^2}{2} P_k
  - \frac{\theta_k}{2} P_{k+1}\\
  &\quad
  + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
  - \frac{\theta_k}{2 \Lest} \inner*{\nabla f(x_k)}{\nabla f(y_k)}.
\end{align}

Next, to bound the last term on the right-hand side, we use the following inequality from \cref{eq:grad_interpolation_error_Mestk}:
\begin{align}
  \norm*{
    \nabla f(y_k)
    - (1 + \theta_k) \nabla f (x_k)
  }
  &\leq
  \theta_k \norm*{ \nabla f(x_{k-1})}
  + 
  \theta_k \Mest_k
  \norm*{x_k - x_{k-1}}^2.
\end{align}
We square both sides as
\begin{alignat}{2}
  &\mathInd
  \norm*{
    \nabla f(y_k)
    - (1 + \theta_k) \nabla f (x_k)
  }^2\\
  &=
  \norm*{\nabla f(y_k)}^2
  + (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
  - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}\\
  &\geq
  (1 + \theta_k)^2 \norm*{\nabla f (x_k)}^2
  - 2 (1 + \theta_k) \inner*{\nabla f (x_k)}{\nabla f(y_k)}
\end{alignat}
and
\begin{alignat}{2}
  \theta_k^2 \prn*{
    \norm*{ \nabla f(x_{k-1})}
    + \Mest_k \norm*{x_k - x_{k-1}}^2
  }^2
  &\leq
  \theta_k (1 + \theta_k) \norm*{ \nabla f(x_{k-1})}^2\\
  &\quad
  + \theta_k^2 (1 + \theta_k) \Mest_k^2 \norm*{x_k - x_{k-1}}^4,
\end{alignat}
where we have used $(a + b)^2 \leq (1 + 1/\theta) a^2 + (1 + \theta) b^2$ for $a, b, \theta > 0$.
Rearranging the terms yields
\[
% \begin{align}
  - \inner*{\nabla f (x_k)}{\nabla f(y_k)}
  \leq
  \frac{\theta_k}{2} \norm*{ \nabla f(x_{k-1})}^2
  - \frac{1 + \theta_k}{2} \norm*{\nabla f (x_k)}^2
  + \frac{\theta_k^2}{2} \Mest_k^2 \norm*{x_k - x_{k-1}}^4.
% \end{align}
\]

Plugging this bound into \cref{eq:descent_f_second} results in
\begin{align}
  \label{eq:hint_potential}
  &\mathInd
  f(x_{k+1}) - f(x_k)\\
  &\leq
  \frac{\theta_k^2}{2} \prn*{
    P_k
    + \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1})}^2
    + \Lest \norm*{x_k - x_{k-1}}^2
  }\\
  &\quad
  -
  \frac{\theta_k}{2} \prn*{
    P_{k+1} + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
  }
  - \frac{\Lest}{2} \norm*{x_{k+1} - x_k}^2\\
  &\quad
  + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
  + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
  - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
\end{align}
This inequality can be rewritten with the potential function $\Phi_k$ defined in \cref{eq:def_potential} as
\begin{align}
  \Phi_{k+1} - \Phi_k
  &\leq
  \frac{\theta_{k+1}^2 - \theta_k}{2}
  \prn*{
    P_{k+1}
    + \frac{1}{2 \Lest} \norm*{\nabla f(x_k)}^2
  }
  + \frac{\theta_{k+1}^2 - 1}{2} \Lest \norm*{x_{k+1} - x_k}^2\\
  &\quad
  + \frac{7 \theta_k^2}{12} \Mest_k \norm*{x_k - x_{k-1}}^3
  + \frac{\theta_k^3}{4 \Lest} \Mest_k^2 \norm*{x_k - x_{k-1}}^4
  - \frac{\theta_k^2}{4 \Lest} \norm*{\nabla f (x_k)}^2.
\end{align}

\begin{proof}[Proof of \cref{lem:decrease_epoch}]
  Note that
  \begin{align}
    \sum_{i=1}^k \norm*{x_i - x_{i-1}}^3
    &\leq
    S_k^{3/2},\quad
    \sum_{i=1}^k \norm*{x_i - x_{i-1}}^4
    \leq
    S_k^2
    \label{eq:sum_xk_diff_power34_upperbound}
  \end{align}
  by the monotonicity of $\ell_p$-norms, i.e., $\norm{a}_p \geq \norm{a}_q$ for $1 \leq p \leq q$.
  In addition, we have
  \begin{align}
    \Phi_k - f(x_k)
    &=
    \frac{\theta_k^2}{2} \prn*{
      \frac{1}{2 \Lest} \norm*{\nabla f(x_{k-1}) + L (x_k - x_{k-1})}^2
      + \frac{\Lest}{2} \norm*{x_k - x_{k-1}}^2
    }
    \geq
    0,
    \label{eq:potential_lowerbound}\\
    \Phi_0 - f(x_0)
    &=
    \frac{\theta_0^2}{4 \Lest} \norm*{\nabla f(x_0)}^2
    \label{eq:potential_obj_0}
  \end{align}
  since $x_{-1} = x_0$.

  Summing \cref{lem:potential_decrease_iteration} over $k$ and telescoping yields
  \begin{align}
    &\mathInd
    \Phi_k - \Phi_0
    \label{eq:potential_decrease_epoch}\\
    &\leq
    \sum_{i=0}^{k-1}
    \bigg(
      \frac{\theta_{i+1}^2 + \theta_i - 2}{4} \Lest \norm*{x_{i+1} - x_i}^2
      + \frac{7 \theta_i^2}{12} \Mest_i \norm*{x_i - x_{i-1}}^3\\
      &\qquad\qquad
      + \frac{\theta_i^3}{4 \Lest} \Mest_i^2 \norm*{x_i - x_{i-1}}^4
      - \frac{\theta_i^2}{4 \Lest} \norm*{\nabla f(x_i)}^2
    \bigg)\\
    &\leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2
    - \frac{\theta_0^2}{4 \Lest} \norm*{\nabla f(x_0)}^2,
  \end{align}
  where we have used \cref{eq:theta_increase_not_too_fast}, \cref{eq:sum_xk_diff_power34_upperbound}, and $\Mest_i \leq \Mest_{k-1}$.
  Combining \cref{eq:potential_lowerbound,eq:potential_obj_0,eq:potential_decrease_epoch} yields
  \begin{align}
    f(x_k) - f(x_0)
    \leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2.
  \end{align}
  Furthermore, we bound the last two terms as
  \begin{alignat}{2}
    &\mathInd
    \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2\\
    &\leq
    \prn*{
      \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} \sqrt{S_{k-1}}
      + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}
    }
    S_k
    &\quad&\by{$S_{k-1} \leq S_k$}\\
    &\leq
    \prn*{
      \frac{7}{12} \theta_{k-1}^2 (1 - \theta_{k-1})^{5/2}
      + \frac{1}{4} \theta_{k-1}^3 (1 - \theta_{k-1})^5
    }
    \Lest S_k
    &\quad&\by{\cref{eq:condition_continue_k-1}}\\
    &\leq
    \prn*{
      \frac{7}{12} + \frac{1}{4}
    }
    \theta_{k-1}^2 (1 - \theta_{k-1})^2
    \Lest S_k
    &\quad&\by{$0 \leq \theta_{k-1} \leq 1$}\\
    &\leq
    \frac{1}{4}
    \theta_{k-1} (1 - \theta_{k-1})
    \Lest S_k
    &\quad&\by{$0 \leq \theta_{k-1} \leq 1$},
  \end{alignat}
  which results in
  \begin{alignat}{2}
    f(x_k) - f(x_0)
    &\leq
    \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
    + \frac{1}{4} \theta_{k-1} (1 - \theta_{k-1}) \Lest S_k\\
    &=
    - \frac{1 - \theta_k}{2} \Lest S_k
    + \frac{(1 - \theta_k)^2 - (1 - \theta_{k-1})^2}{4} \Lest S_k\\
    &\leq
    - \frac{1 - \theta_k}{2} \Lest S_k
    &\quad&\by{\cref{eq:theta_increase_not_too_fast}}
  \end{alignat}
  and concludes the proof.
\end{proof}

Furthermore, we bound the last two terms as
\begin{alignat}{2}
  &\mathInd
  \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} S_{k-1}^{3/2} 
  + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}^2\\
  &\leq
  \prn*{
    \frac{7 \theta_{k-1}^2}{12} \Mest_{k-1} \sqrt{S_{k-1}}
    + \frac{\theta_{k-1}^3}{4 \Lest} \Mest_{k-1}^2 S_{k-1}
  }
  S_k
  &\quad&\by{$S_{k-1} \leq S_k$}\\
  &\leq
  \prn*{
    \frac{7}{12} \theta_{k-1}^2 (1 - \theta_{k-1})^{5/2}
    + \frac{1}{4} \theta_{k-1}^3 (1 - \theta_{k-1})^5
  }
  \Lest S_k
  &\quad&\by{\cref{eq:condition_continue_k-1}}\\
  &\leq
  \prn*{
    \frac{7}{12} + \frac{1}{4}
  }
  \theta_{k-1}^2 (1 - \theta_{k-1})^2
  \Lest S_k
  &\quad&\by{$0 \leq \theta_{k-1} \leq 1$}\\
  &\leq
  \frac{1}{4}
  \theta_{k-1} (1 - \theta_{k-1})
  \Lest S_k
  &\quad&\by{$0 \leq \theta_{k-1} \leq 1$},
\end{alignat}
which results in
\begin{alignat}{2}
  f(x_k) - f(x_0)
  &\leq
  \frac{\theta_k^2 + \theta_{k-1} - 2}{4} \Lest S_k
  + \frac{1}{4} \theta_{k-1} (1 - \theta_{k-1}) \Lest S_k\\
  &=
  - \frac{1 - \theta_k}{2} \Lest S_k
  + \frac{(1 - \theta_k)^2 - (1 - \theta_{k-1})^2}{4} \Lest S_k\\
  &\leq
  - \frac{1 - \theta_k}{2} \Lest S_k
  &\quad&\by{\cref{eq:theta_increase_not_too_fast}}
\end{alignat}
and concludes the proof.

\begin{proposition}
  \label{prop:Mk_upperbound}
  Suppose that \cref{asm:hessian_lip} holds.
  Then, the following is true throughout \cref{alg:proposed_agd}: 
  $\Mest_k \leq \max\set{M_0, \Mtrue}$.
\end{proposition}

\begin{lemma}
  \label{lem:grad_interpolation_error}
  Under \cref{asm:hessian_lip}, the following hold for all $k \geq 1$:
  \begin{align}
    &
    \norm*{
      \nabla f(y_k)
      + \theta_k \nabla f(x_{k-1})
      - (1 + \theta_k) \nabla f (x_k)
    }
    \leq
    \theta_k \Mtrue \norm*{x_k - x_{k-1}}^2,
    \label{eq:grad_interpolation_error_Mf}\\

\begin{lemma}
  \label{lem:grad_interpolation_error}
  Under \cref{asm:hessian_lip}, the following hold for all $k \geq 1$:

    &
    \norm*{ \nabla f (\bar y_k) }
    \leq
    \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
    + \frac{(k-1) (k+5)^2}{16 Z_k^2} \Mtrue S_k.
    \label{eq:grad_ybark_upperbound_Mf}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{eq:grad_ybark_upperbound_Mf}]
  We have
  \begin{alignat}{2}
    &\mathInd
    p_{k,i} \nabla f(y_i)
    =
    p_{k,i} \Lest (y_i - x_{i+1})\\
    &=
    p_{k,i} \Lest \prn*{
      \theta_i (x_i - x_{i-1})
      - (x_{i+1} - x_i)
    }
    &\quad&\by{\cref{eq:update_xy}}\\
    &=
    \Lest \prn*{
      p_{k,i-1} (x_i - x_{i-1})
      - p_{k,i} (x_{i+1} - x_i)
    }
    &\quad&\by{definition \cref{eq:def_ybark} of $p_{k,i}$}.
  \end{alignat}
  Summing this equality over $i$ yields
  \begin{align}
    \sum_{i=0}^{k-1}
    p_{k,i} \nabla f(y_i)
    =
    - \Lest p_{k,k-1} (x_k - x_{k-1}),
    \label{eq:weighted_average_gradient_equation}
  \end{align}
  where we have used $x_0 = x_{-1}$.
  Now, we obtain
  \begin{alignat}{2}
    &\mathInd
    \norm*{
      \nabla f (\bar y_k)
    }
    \label{eq:norm_grad_ybark_upperbound_pre}\\
    &\leq
    \norm*{
      \sum_{i=0}^{k-1} p_{k,i} \nabla f \prn*{ y_i }
    }
    + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
    &\quad&\by{\cref{lem:gradient_jensen}}\\
    &=
    \Lest p_{k,k-1} \norm*{x_k - x_{k-1}}
    + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
    &\quad&\by{\cref{eq:weighted_average_gradient_equation}}\\
    &\leq
    \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
    + \frac{\Mtrue}{2 Z_k^2} \sum_{0 \leq i < j < k} \norm*{y_i - y_j}^2,
  \end{alignat}
  where the last inequality follows from $p_{k,i} \leq p_{k,k-1} = 1 / Z_k$ for all $0 \leq i < k$.

  Next, we bound the second term on the right-hand side.
  Since for $0 \leq i < j < k$,
  \begin{alignat}{2}
    &\mathInd
    \norm*{y_i - y_j}\\
    &\leq
    \norm*{y_i - x_i}
    + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
    + \norm*{y_j - x_{j-1}}
    &\quad&\by{the triangle inequality}\\
    &=
    \norm*{x_i - x_{i-1}}
    + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
    + 2 \norm*{x_j - x_{j-1}}
    &\quad&\by{\cref{eq:update_xy} and $0 \leq \theta_k \leq 1$}\\
    &\leq
    \prn*{
      1^2 + \sum_{l=i+1}^{j-1} 1^2 + 2^2
    }^{1/2}
    \prn*{
      \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
    }^{1/2}
    &\quad&\by{Cauchy--Schwarz}\\
    &=
    \sqrt{j - i + 4}
    \prn*{
      \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
    }^{1/2},
  \end{alignat}
  we have
  \begin{align}
    \sum_{0 \leq i < j < k}
    \norm*{y_i - y_j}^2
    &\leq
    \sum_{0 \leq i < j < k}
    \sum_{l=i}^j
    (j - i + 4) \norm*{x_l - x_{l-1}}^2\\
    % &=
    % \sum_{0 \leq i \leq l \leq j < k}
    % (j - i + 4) \norm*{x_l - x_{l-1}}^2
    % - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \sum_{l=0}^{k-1}
    \prn*{
      \sum_{i=0}^l
      \sum_{j=l}^{k-1}
      (j - i + 4) 
    }
    \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \frac{k + 7}{2}
    \sum_{l=0}^{k-1}
    (l + 1) (k - l)
    \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &\leq
    \frac{k + 7}{2}
    \sum_{l=0}^{k-1} \frac{(k+1)^2}{4} \norm*{x_l - x_{l-1}}^2
    - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
    &=
    \frac{(k-1) (k+5)^2}{8}
    \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2
    \leq
    \frac{(k-1) (k+5)^2}{8} S_k.
  \end{align}
  Plugging this bound into \cref{eq:norm_grad_ybark_upperbound_pre} concludes the proof.
\end{proof}

We have
\begin{alignat}{2}
  &\mathInd
  p_{k,i} \nabla f(y_i)
  =
  p_{k,i} \Lest (y_i - x_{i+1})\\
  &=
  p_{k,i} \Lest \prn*{
    \theta_i (x_i - x_{i-1})
    - (x_{i+1} - x_i)
  }
  &\quad&\by{\cref{eq:update_xy}}\\
  &=
  \Lest \prn*{
    p_{k,i-1} (x_i - x_{i-1})
    - p_{k,i} (x_{i+1} - x_i)
  }
  &\quad&\by{definition \cref{eq:def_ybark} of $p_{k,i}$}.
\end{alignat}
Summing this equality over $i$ yields
\begin{align}
  \sum_{i=0}^{k-1}
  p_{k,i} \nabla f(y_i)
  =
  - \Lest p_{k,k-1} (x_k - x_{k-1}),
  \label{eq:weighted_average_gradient_equation}
\end{align}
where we have used $x_0 = x_{-1}$.

Now, we obtain
\begin{alignat}{2}
  &\mathInd
  \norm*{
    \nabla f (\bar y_k)
  }
  \label{eq:norm_grad_ybark_upperbound_pre}\\
  &\leq
  \norm*{
    \sum_{i=0}^{k-1} p_{k,i} \nabla f \prn*{ y_i }
  }
  + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
  &\quad&\by{\cref{lem:gradient_jensen}}\\
  &=
  \Lest p_{k,k-1} \norm*{x_k - x_{k-1}}
  + \frac{\Mtrue}{2} \sum_{0 \leq i < j < k} p_{k,i} p_{k,j} \norm*{y_i - y_j}^2
  &\quad&\by{\cref{eq:weighted_average_gradient_equation}}\\
  &\leq
  \frac{\Lest}{Z_k} \norm*{x_k - x_{k-1}}
  + \frac{\Mtrue}{2 Z_k^2} \sum_{0 \leq i < j < k} \norm*{y_i - y_j}^2,
\end{alignat}
where the last inequality follows from $p_{k,i} \leq p_{k,k-1} = 1 / Z_k$ for all $0 \leq i < k$.

Next, we bound the second term on the right-hand side.
Since for $0 \leq i < j < k$,
\begin{alignat}{2}
  &\mathInd
  \norm*{y_i - y_j}\\
  &\leq
  \norm*{y_i - x_i}
  + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
  + \norm*{y_j - x_{j-1}}
  &\quad&\by{the triangle inequality}\\
  &=
  \norm*{x_i - x_{i-1}}
  + \sum_{l=i+1}^{j-1} \norm*{x_l - x_{l-1}}
  + 2 \norm*{x_j - x_{j-1}}
  &\quad&\by{\cref{eq:update_xy} and $0 \leq \theta_k \leq 1$}\\
  &\leq
  \prn*{
    1^2 + \sum_{l=i+1}^{j-1} 1^2 + 2^2
  }^{1/2}
  \prn*{
    \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
  }^{1/2}
  &\quad&\by{Cauchy--Schwarz}\\
  &=
  \sqrt{j - i + 4}
  \prn*{
    \sum_{l=i}^j \norm*{x_l - x_{l-1}}^2
  }^{1/2},
\end{alignat}

we have
\begin{align}
  \sum_{0 \leq i < j < k}
  \norm*{y_i - y_j}^2
  &\leq
  \sum_{0 \leq i < j < k}
  \sum_{l=i}^j
  (j - i + 4) \norm*{x_l - x_{l-1}}^2\\
  % &=
  % \sum_{0 \leq i \leq l \leq j < k}
  % (j - i + 4) \norm*{x_l - x_{l-1}}^2
  % - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
  &=
  \sum_{l=0}^{k-1}
  \prn*{
    \sum_{i=0}^l
    \sum_{j=l}^{k-1}
    (j - i + 4) 
  }
  \norm*{x_l - x_{l-1}}^2
  - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
  &=
  \frac{k + 7}{2}
  \sum_{l=0}^{k-1}
  (l + 1) (k - l)
  \norm*{x_l - x_{l-1}}^2
  - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
  &\leq
  \frac{k + 7}{2}
  \sum_{l=0}^{k-1} \frac{(k+1)^2}{4} \norm*{x_l - x_{l-1}}^2
  - 4 \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2\\
  &=
  \frac{(k-1) (k+5)^2}{8}
  \sum_{l=0}^{k-1} \norm*{x_l - x_{l-1}}^2
  \leq
  \frac{(k-1) (k+5)^2}{8} S_k.
\end{align}
Plugging this bound into \cref{eq:norm_grad_ybark_upperbound_pre} concludes the proof.

\begin{lemma}
  \label{lem:grad_norm_ybar_upperbound}
  Suppose that \cref{asm:gradient_hessian_lip} holds.
  In \cref{alg:proposed_agd}, the following is true when $k \geq 2$:
  \begin{align}
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lmax^2 \Mmax}{M_0^2 k^4}.
    \label{eq:grad_norm_ybar_upperbound}
  \end{align}

\begin{lemma}
  \label{lem:grad_norm_ybar_upperbound}
  Suppose that \cref{asm:gradient_hessian_lip} holds.
  In \cref{alg:proposed_agd}, the following is true when $k \geq 2$:

  If $M_k$ is computed with \cref{eq:update_Mest} in the algorithm, the above bound is improved to
  \begin{align}
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    4 \Lest \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lmax^2}{M_0 k^4}.
    \label{eq:grad_norm_ybar_upperbound_tight}
  \end{align}
\end{lemma}

\begin{proof}[Proof of \cref{eq:grad_norm_ybar_upperbound}] 
  Note that
  \begin{align}
    &\sum_{i=1}^{k-1}
    \frac{(i-1)(i+5)^2}{16}
    =
    \frac{(k - 2) (k - 1) (k^2 + 13 k + 50)}{64}
    \leq
    \frac{k^3 (k+1)}{24},
    \label{eq:i_cubic_sum}\\
    &\sum_{i=1}^{k-1} Z_i^2
    =
    \sum_{i=1}^{k-1} \prn*{\frac{i+1}{2}}^2
    =
    \frac{(k-1) (2 k^2 + 5 k + 6)}{24}
    \geq 
    \frac{k^2 (k+1)}{12}
    \label{eq:Zi_squared_sum}
  \end{align}
  from \cref{eq:ybar_Zk_alternative} and $k \geq 2$.
  Using \cref{eq:grad_ybark_upperbound_Mf}, we have
  \begin{align}
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }
    &\leq
    \sum_{i=1}^{k-1}
    Z_i^2
    \norm*{ \nabla f (\bar y_i) }\\
    &\leq
    \sum_{i=1}^{k-1}
    \prn*{
      \Lest Z_i \norm*{x_i - x_{i-1}}
      + \frac{(i-1) (i+5)^2}{16} \Mtrue S_i
    }.
  \end{align}
  Each term on the right-hand side can be bounded as follows:
  \begin{alignat}{2}
    &\sum_{i=1}^{k-1} \Lest Z_i \norm*{x_i - x_{i-1}}
    \leq
    \Lest
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{1/2}
    \sqrt{S_{k-1}}
    &\quad&\by{Cauchy--Schwarz},\\
    &\sum_{i=1}^{k-1}
    \frac{(i-1)(i+5)^2}{16} \Mtrue S_i
    \leq
    \frac{k^3 (k+1)}{24}
    \Mtrue S_{k-1}
    &\quad&\by{\cref{eq:i_cubic_sum}}.
  \end{alignat}
  We thus have
  \begin{alignat}{2}
    &\mathInd
    \min_{1 \leq i < k} \norm*{ \nabla f (\bar y_i) }\\
    &\leq
    \Lest 
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{-1/2}\!\!
    \sqrt{S_{k-1}}
    + 
    \prn*{
      \sum_{i=1}^{k-1} Z_i^2
    }^{-1}
    \frac{k^3 (k+1)}{24}
    \Mtrue S_{k-1}\\
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{k}{2}
    \Mtrue S_{k-1}
    &\quad&\by{\cref{eq:Zi_squared_sum}}\\
    &\leq
    \Lest 
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{\Lest \Mtrue}{2 \Mest_k} 
    \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{\cref{eq:condition_continue_k-1}}\\
    &\leq
    \frac{\Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{12 S_{k-1}}{k^3}}
    +
    \frac{\Lest \Mmax}{2 \Mest_{k-1}} 
    \sqrt{\frac{S_{k-1}}{k^3}}
    &\quad&\by{$\Mest_{k-1}, \Mtrue \leq \Mmax$}\\
    &\leq
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}},
  \end{alignat}
  which is the first inequality of the desired result~\cref{eq:grad_norm_ybar_upperbound}.
  The second inequality follows from \cref{eq:condition_continue_k-1}:
  \begin{align}
    \frac{4 \Lest \Mmax}{\Mest_{k-1}}
    \sqrt{\frac{S_{k-1}}{k^3}}
    \leq
    \frac{4 \Lest^2 \Mmax}{M_{k-1}^2 k^4}
    \leq
    \frac{4 \Lmax^2 \Mmax}{M_0 k^4}.
  \end{align}
\end{proof}

Note that
\begin{align}
  &\sum_{i=1}^{k-1}
